.weapon-name small{font-size:7px;letter-spacing:1px;color:#778984}
.ammo{margin-left:auto;display:flex;align-items:baseline;gap:4px}
.ammo b{font-size:19px;font-weight:800}
.ammo span,.ammo small{color:#889691;font-size:10px}
.squad-panel{position:absolute;z-index:2;right:24px;bottom:25px;width:176px;padding:10px 12px;background:rgba(11,21,24,.77);border:1px solid rgba(220,238,230,.12);pointer-events:none}
.squad-label{display:flex;justify-content:space-between;font-size:8px;font-weight:800;letter-spacing:1.2px;color:#c3d0c9}
.squad-label span{font-size:7px;color:#71cbb8}
.squad-pips{display:flex;gap:5px;margin-top:9px}
.squad-pip{flex:1;height:5px;background:#71d7c0;transition:opacity .2s}
.squad-pip.dead{background:#687571;opacity:.35}
.objective-hint{position:absolute;z-index:2;left:50%;bottom:27px;transform:translateX(-50%);display:flex;align-items:center;gap:9px;padding:9px 13px;background:rgba(12,22,25,.75);border:1px solid rgba(220,238,230,.13);pointer-events:none}
.objective-icon{font-size:18px;color:var(--orange)}
.objective-hint b{display:block;font-size:8px;letter-spacing:1.3px}
.objective-hint small{display:block;font-size:7px;color:#93a39d;margin-top:3px;letter-spacing:1px}
.kill-feed{position:absolute;z-index:2;right:25px;top:94px;display:flex;flex-direction:column;align-items:flex-end;gap:5px;pointer-events:none}
.feed-item{font-size:9px;letter-spacing:.3px;padding:7px 10px;background:rgba(12,22,25,.7);border-right:2px solid var(--teal);color:#e2ece5;animation:feed-in .2s ease-out}
.feed-item.enemy{border-color:var(--orange)}
@keyframes feed-in{from{transform:translateX(12px);opacity:0}
to{transform:none;opacity:1}
}
.toast{position:absolute;z-index:3;top:25%;left:50%;transform:translate(-50%,-10px);padding:9px 15px;background:rgba(12,22,25,.9);border:1px solid rgba(117,216,198,.3);font-size:9px;letter-spacing:1.2px;color:#dff5e9;opacity:0;transition:opacity .2s,transform .2s;pointer-events:none}
.toast.show{opacity:1;transform:translate(-50%,0)}
.reticle{position:absolute;z-index:3;left:50%;top:50%;width:25px;height:25px;transform:translate(-50%,-50%);pointer-events:none;transition:opacity .1s}
.reticle i{position:absolute;background:rgba(237,246,236,.9);box-shadow:0 0 3px #162522}
.reticle i:nth-child(1){width:2px;height:6px;left:11px;top:0}
.reticle i:nth-child(2){width:2px;height:6px;left:11px;bottom:0}
.reticle i:nth-child(3){width:6px;height:2px;left:0;top:11px}
.reticle i:nth-child(4){width:6px;height:2px;right:0;top:11px}
.reticle b{position:absolute;inset:10px;border:1px solid rgba(117,216,198,.9);border-radius:50%}
.hit-marker{position:absolute;z-index:4;left:50%;top:50%;transform:translate(-50%,-50%);color:#f4d18e;font-size:34px;font-weight:300;pointer-events:none;text-shadow:0 1px 5px #000}
.controls{position:absolute;z-index:4;left:0;right:0;bottom:0;height:190px;pointer-events:none}
.move-pad{position:absolute;left:22px;bottom:21px;width:132px;height:132px;pointer-events:auto;touch-action:none}
.pad-ring{position:absolute;inset:0;border-radius:50%;border:1px solid rgba(222,240,229,.32);background:rgba(17,30,32,.36);box-shadow:inset 0 0 30px rgba(190,225,211,.07)}
.pad-knob{position:absolute;left:50%;top:50%;width:54px;height:54px;border-radius:50%;transform:translate(-50%,-50%);border:1px solid rgba(222,240,229,.55);background:rgba(201,232,218,.22);box-shadow:0 3px 14px rgba(0,0,0,.2)}
.pad-label{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);font-size:7px;font-weight:800;letter-spacing:1px;color:rgba(237,246,236,.5);pointer-events:none}
.touch-actions{position:absolute;right:23px;bottom:20px;display:flex;align-items:flex-end;gap:14px;pointer-events:auto}
.fire-button{width:90px;height:90px;border-radius:50%;border:1px solid rgba(244,178,132,.72);background:rgba(184,95,61,.38);box-shadow:inset 0 0 0 7px rgba(244,178,132,.08),0 6px 20px rgba(0,0,0,.2);display:flex;flex-direction:column;justify-content:center;align-items:center;gap:2px;touch-action:none}
.fire-button:active{background:rgba(220,126,78,.68);transform:scale(.97)}
.fire-cross{font-size:24px;line-height:1;color:#ffd2af}
.fire-button b{font-size:8px;letter-spacing:1.5px}
.action-button{width:58px;height:58px;border-radius:50%;border:1px solid rgba(218,237,226,.36);background:rgba(14,26,29,.62);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;touch-action:none}
.action-button span{font-size:22px;color:#d8e6de;line-height:1}
.action-button small{font-size:6px;letter-spacing:.8px;color:#c0cec7}
.round-screen,.pause-screen{background:rgba(8,15,18,.57);backdrop-filter:blur(6px)}
.round-card{width:min(440px,calc(100% - 42px));padding:33px 35px;background:rgba(15,26,29,.97);border:1px solid rgba(213,234,222,.17);box-shadow:0 25px 90px rgba(0,0,0,.48);text-align:center}
.round-card .eyebrow{justify-content:center}
.round-card h2{margin:13px 0 7px;font-size:33px;letter-spacing:1px}
.round-card>p{margin:0;color:#99aaa3;font-size:13px}
.round-result{display:flex;align-items:center;justify-content:space-between;margin:23px 0 7px;padding:12px 15px;background:rgba(219,237,225,.05);font-size:9px;letter-spacing:1.5px;color:#91aaa2}
.round-result b{font-size:18px;letter-spacing:1px;color:#e6eee8}
.round-card .primary-button{width:100%}
.text-button{margin-top:17px;border:0;background:none;color:#80938c;font-size:9px;letter-spacing:1.3px;cursor:pointer}
